input.command:
sqlite3 /data/maps/e2e_test_case_0.Civ6Map << 'EOF'
-- Get map dimensions
.mode column
.headers on
SELECT Width, Height FROM Map;

-- Get terrain distribution with coordinates
SELECT COUNT(*) as count, TerrainType FROM Plots GROUP BY TerrainType ORDER BY count DESC;

-- Get all grass/plains terrain tiles (buildable land)
SELECT ID, TerrainType FROM Plots WHERE TerrainType IN ('TERRAIN_GRASS', 'TERRAIN_PLAINS', 'TERRAIN_GRASS_MOUNTAIN') ORDER BY ID;

-- Get start positions
SELECT * FROM StartPositions;
EOF
